messages.content:
{
  "type": "object",
  "properties": {
    "type": {
      "enum": [
        "video_url",
        "input_video"
      ]
    },
    "video_url": {
      "type": "object",
      "properties": {
        "url": {
          "type": "string",
          "description": "URL of the video."
        }
      },
      "required": [
        "url"
      ]
    }
  },
  "required": [
    "type",
    "video_url"
  ],
  "description": "A video rich content part."
}

{
  "type": "object",
  "properties": {
    "role": {
      "const": "user"
    },
    "content": {
      "anyOf": [
        {
          "type": "string",
          "description": "Plain text content."
        },
        {
          "type": "array",
          "items": {
            "$ref": "RichContentPart",
            "description": "A rich content part."
          },
          "description": "An array of rich content parts."
        }
      ],
      "description": "Rich content."
    },
    "name": {
      "anyOf": [
        {
          "type": "string",
          "description": "An optional name for the participant. Provides the model information to differentiate between participants of the same role."
        },
        {
          "type": "null"
        }
      ]
    }
  },
  "required": [
    "role",
    "content"
  ],
  "description": "Messages sent by an end user, containing prompts or additional context information."
}

{
  "anyOf": [
    {
      "$ref": "DeveloperMessage",
      "description": "Developer-provided instructions that the model should follow, regardless of messages sent by the user."
    },
    {
      "$ref": "SystemMessage",
      "description": "Developer-provided instructions that the model should follow, regardless of messages sent by the user."
    },
    {
      "$ref": "UserMessage",
      "description": "Messages sent by an end user, containing prompts or additional context information."
    },
    {
      "$ref": "ToolMessage",
      "description": "Messages sent by tools in response to tool calls made by the assistant."
    },
    {
      "$ref": "AssistantMessage",
      "description": "Messages sent by the model in response to user messages."
    }
  ],
  "description": "A message exchanged in a chat conversation."
}

{
  "type": "object",
  "properties": {
    "type": {
      "const": "vector.completion"
    },
    "skip": {
      "$ref": "Expression",
      "description": "An expression which evaluates to a boolean indicating whether to skip this task. Receives: `input`."
    },
    "messages": {
      "$ref": "Expression",
      "description": "An expression which evaluates to the chat messages. Receives: `input`."
    },
    "responses": {
      "type": "array",
      "items": {
        "anyOf": [
          {
            "type": "string",
            "description": "Plain text content."
          },
          {
            "type": "array",
            "items": {
              "$ref": "RichContentPart",
              "description": "A rich content part."
            },
            "description": "An array of rich content parts."
          }
        ],
        "description": "Rich content."
      },
      "description": "The response options for the vector completion."
    }
  },
  "required": [
    "type",
    "messages",
    "responses"
  ],
  "description": "A vector completion task expression for an alpha scalar leaf function."
}
